// src/network/visitor_client.ts
export type Visitor = { id: number; title: string };

type NewVisitor = Omit<Visitor, "id">;

export async function listVisitor(): Promise<Visitor[]> {
  const res = await fetch("/api/visitors");
  return res.json();
}

export async function createVisitor(payload: NewVisitor): Promise<Visitor> {
  const res = await fetch("/api/visitors", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

