export const route = "/campers";

type Row = { id: number; title: string };

export function CamperPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/campers")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
