import { useEffect, useState } from "react";

export const route = "/hives";

type Row = { id: number; title: string };

export function HivePage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/hives")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Hive</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

