// src/frontend/CharterPage.tsx
import { useEffect, useState } from "react";

export const route = "/charters";

type Row = { id: number; title: string };

export function CharterPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/charters")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Charter</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

