// src/network/charter_client.ts
export type Charter = { id: number; title: string };

type NewCharter = Omit<Charter, "id">;

export async function listCharter(): Promise<Charter[]> {
  const res = await fetch("/api/charters");
  return res.json();
}

export async function createCharter(payload: NewCharter): Promise<Charter> {
  const res = await fetch("/api/charters", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

