# src/network/hive_api.py
from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["hive"])


@router.get("/api/hives")
async def list_hives(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM hive ORDER BY id DESC")


@router.post("/api/hives")
async def create_hive(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO hive (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/hives/{item_id}")
async def get_hive(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM hive WHERE id = $1", item_id)

