// src/network/hive_client.ts
export type Hive = { id: number; title: string };

type NewHive = Omit<Hive, "id">;

export async function listHive(): Promise<Hive[]> {
  const res = await fetch("/api/hives");
  return res.json();
}

export async function createHive(payload: NewHive): Promise<Hive> {
  const res = await fetch("/api/hives", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

