from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["cabin"])


@router.get("/api/cabins")
async def list_cabins(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM cabin ORDER BY id DESC")


@router.post("/api/cabins")
async def create_cabin(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO cabin (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/cabins/{item_id}")
async def get_cabin(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM cabin WHERE id = $1", item_id)

