import { useEffect, useState } from "react";

export const route = "/listings";

type Row = { id: number; title: string };

export function ListingPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/listings")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Listing</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

