# src/network/listing_api.py
from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["listing"])


@router.get("/api/listings")
async def list_listings(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM listing ORDER BY id DESC")


@router.post("/api/listings")
async def create_listing(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO listing (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/listings/{item_id}")
async def get_listing(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM listing WHERE id = $1", item_id)

