// src/frontend/CabinPage.tsx
import { useEffect, useState } from "react";

export const route = "/cabins";

type Row = { id: number; title: string };

export function CabinPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/cabins")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Cabin</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

