// src/network/camper_client.ts
export type Camper = { id: number; title: string };

type NewCamper = Omit<Camper, "id">;

export async function listCamper(): Promise<Camper[]> {
  const res = await fetch("/api/campers");
  return res.json();
}

export async function createCamper(payload: NewCamper): Promise<Camper> {
  const res = await fetch("/api/campers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

