// src/frontend/ConsignorPage.tsx
import { useEffect, useState } from "react";

export const route = "/consignors";

type Row = { id: number; title: string };

export function ConsignorPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/consignors")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Consignor</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

