# src/network/consignor_api.py
from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["consignor"])


@router.get("/api/consignors")
async def list_consignors(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM consignor ORDER BY id DESC")


@router.post("/api/consignors")
async def create_consigner(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO consignor (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/consignors/{item_id}")
async def get_consigner(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM consignor WHERE id = $1", item_id)

