// src/network/listing_client.ts
export type Listing = { id: number; title: string };

type NewListing = Omit<Listing, "id">;

export async function listListing(): Promise<Listing[]> {
  const res = await fetch("/api/listings");
  return res.json();
}

export async function createListing(payload: NewListing): Promise<Listing> {
  const res = await fetch("/api/listings", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

