from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["batch"])


@router.get("/api/batches")
async def list_batches(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM batch ORDER BY id DESC")


@router.post("/api/batches")
async def create_batch(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO batch (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/batches/{item_id}")
async def get_batch(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM batch WHERE id = $1", item_id)

