// src/network/recipe_card_client.ts
export type RecipeCard = { id: number; title: string };

type NewRecipeCard = Omit<RecipeCard, "id">;

export async function listRecipeCard(): Promise<RecipeCard[]> {
  const res = await fetch("/api/recipe_cards");
  return res.json();
}

export async function createRecipeCard(payload: NewRecipeCard): Promise<RecipeCard> {
  const res = await fetch("/api/recipe_cards", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

