from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["honey_jar"])


@router.get("/api/honey_jars")
async def list_honey_jars(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM honey_jar ORDER BY id DESC")


@router.post("/api/honey_jars")
async def create_honey_jar(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO honey_jar (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/honey_jars/{item_id}")
