export type Inspection = { id: number; title: string };

type NewInspection = Omit<Inspection, "id">;

export async function listInspection(): Promise<Inspection[]> {
  const res = await fetch("/api/inspections");
  return res.json();
}

export async function createInspection(payload: NewInspection): Promise<Inspection> {
  const res = await fetch("/api/inspections", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

