from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["charter"])


@router.get("/api/charters")
async def list_charters(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM charter ORDER BY id DESC")


@router.post("/api/charters")
async def create_charter(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO charter (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/charters/{item_id}")
async def get_charter(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM charter WHERE id = $1", item_id)

