export type Tutor = { id: number; title: string };

type NewTutor = Omit<Tutor, "id">;

export async function listTutor(): Promise<Tutor[]> {
  const res = await fetch("/api/tutors");
  return res.json();
}

export async function createTutor(payload: NewTutor): Promise<Tutor> {
  const res = await fetch("/api/tutors", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

