export const route = "/visitors";

type Row = { id: number; title: string };

export function VisitorPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/visitors")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Visitor</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

