# src/network/actor_api.py
from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["actor"])


@router.get("/api/actors")
async def list_actors(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM actor ORDER BY id DESC")


@router.post("/api/actors")
async def create_actor(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO actor (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/actors/{item_id}")
async def get_actor(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM actor WHERE id = $1", item_id)

