// src/network/crew_member_client.ts
export type CrewMember = { id: number; title: string };

type NewCrewMember = Omit<CrewMember, "id">;

export async function listCrewMember(): Promise<CrewMember[]> {
  const res = await fetch("/api/crew_members");
  return res.json();
}

export async function createCrewMember(payload: NewCrewMember): Promise<CrewMember> {
  const res = await fetch("/api/crew_members", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

