export type Subject = { id: number; title: string };

type NewSubject = Omit<Subject, "id">;

export async function listSubject(): Promise<Subject[]> {
  const res = await fetch("/api/subjects");
  return res.json();
}

export async function createSubject(payload: NewSubject): Promise<Subject> {
  const res = await fetch("/api/subjects", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

