// src/network/voucher_client.ts
export type Voucher = { id: number; title: string };

type NewVoucher = Omit<Voucher, "id">;

export async function listVoucher(): Promise<Voucher[]> {
  const res = await fetch("/api/vouchers");
  return res.json();
}

export async function createVoucher(payload: NewVoucher): Promise<Voucher> {
  const res = await fetch("/api/vouchers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

